const effects=[
{id:'spatial',name:'3D stereo',icon:'◇',desc:'A wider stereo image.',detail:'Expand the difference between the left and right channels.',controls:[['Width',160,0,250,'%','Mono','Extra wide']],note:'100% preserves stereo width. Mono recordings remain centered; use 8D for movement.'},
{id:'pan',name:'Stereo panner',icon:'↔',desc:'Place sound left or right.',detail:'Set a fixed position in the stereo field.',controls:[['Position',-35,-100,100,'%','Left','Right']],note:'0% is centered. Negative values move left; positive values move right. Exports stereo audio.'},
{id:'trim',name:'Trimmer / cutter',icon:'✂',desc:'Keep the section you want.',detail:'Choose the start and end as percentages of the audio at this point in the chain.',controls:[['Start',0,0,99,'%','Beginning','End'],['End',100,1,100,'%','Beginning','End']],note:'Only the selected section is kept. Start must be less than end. Full range keeps the whole track.'},
{id:'tuning',name:'432 Hz tuning',icon:'♬',desc:'Lower concert tuning slightly.',detail:'Shift a recording tuned to A=440 Hz down to A=432 Hz, keeping its duration.',controls:[],note:'A subtle pitch shift of about −0.318 semitones. This assumes the source was tuned to 440 Hz.'},
{id:'eightd',name:'8D audio',icon:'∞',desc:'Sound that moves around you.',detail:'Sweep the audio smoothly between your left and right ears.',controls:[['Rotation time',8,2,20,' seconds','Fast','Slow'],['Movement',100,0,100,'%','Center','Wide']],note:'Listen with headphones. Creates a moving stereo effect, including from mono audio. Combine with Reverb for more space.'},
{id:'equalizer',name:'Equalizer',icon:'≋',desc:'Shape eight frequency bands.',detail:'Fine-tune the lows, mids and highs independently.',controls:['60 Hz','150 Hz','400 Hz','1 kHz','2.4 kHz','6 kHz','10 kHz','16 kHz'].map(label=>[label,0,-18,18,' dB','Cut','Boost']),note:'Starts flat at 0 dB. Adjust a band to change the sound, then Apply effects. Strong boosts are attenuated when needed to prevent clipping.'},
{id:'reverb',name:'Reverb',icon:'◴',desc:'Room to concert hall.',detail:'Add clear early reflections and a dense, spacious decay.',controls:[['Room size',95,0,100,'%','Small room','Large hall'],['Reverb mix',51,0,100,'%','Dry','Wet']],note:'The mix now includes stronger reflections and a full decay tail. Try 60–80% for an obvious spacious sound.'},
{id:'slowed',name:'Slowed + reverb',icon:'◷',desc:'Slow down. Drift away.',detail:'Slow the recording and lower its pitch, with spacious reverb.',controls:[['Speed',80,50,100,'%','0.5×','1.0×'],['Reverb mix',35,0,100,'%','Dry','Wet']],note:'This classic slowed effect lowers pitch too. Use Tempo control to preserve pitch.'},
{id:'bass',name:'Bass boost',icon:'▥',desc:'Weight and warmth.',detail:'Add a powerful boost to bass and low-end warmth.',controls:[['Bass gain',27,0,30,' dB','Neutral','Deep'],['Frequency',140,40,400,' Hz','40 Hz','400 Hz']],note:'Strong boosts are automatically attenuated if needed to prevent clipping.'},
{id:'loudness',name:'Loudness',icon:'◖',desc:'Turn the audio up or down.',detail:'Change the loudness of the exported audio.',controls:[['Gain',6,-24,24,' dB','Quieter','Louder']],note:'Applied after the other effects. 0 dB keeps the level unchanged. A soft limiter controls boosted peaks; large boosts can add saturation.'},
{id:'treble',name:'Treble',icon:'⌁',desc:'Soften or brighten the highs.',detail:'Cut or boost the high frequencies, from a mellow sound to bright treble.',controls:[['Treble gain',-18,-18,24,' dB','Softer','Brighter'],['Frequency',1000,1000,10000,' Hz','1 kHz','10 kHz']],note:'Defaults to a strong high-frequency cut: −18 dB at 1 kHz. Raise the gain above 0 dB for a brighter sound.'},
{id:'reverse',name:'Reverse audio',icon:'↶',desc:'Turn time around.',detail:'Play the whole recording backward.',controls:[],note:'Reverses every channel, including speech, music and transients. Apply again always starts from the original.'},
{id:'radio',name:'Telephone / radio',icon:'☎',desc:'Vintage broadcast sound.',detail:'Remove deep bass and high treble for a narrow telephone or radio sound.',controls:[['Low cutoff',400,100,1000,' Hz','Radio','Telephone'],['High cutoff',2800,1500,6000,' Hz','Narrow','Wide']],note:'Use 400–2800 Hz for a telephone, or 150–5000 Hz for a wider radio tone.'},
{id:'distortion',name:'Distortion',icon:'ϟ',desc:'Warm crunch to heavy grit.',detail:'Drive the waveform into smooth saturation.',controls:[['Drive',55,0,100,'%','Clean','Heavy'],['Mix',70,0,100,'%','Dry','Distorted']],note:'Adds harmonics and compresses peaks. Lower the mix to keep some of the clean sound.'},
{id:'sped',name:'Sped up',icon:'»',desc:'Faster with a higher pitch.',detail:'Speed up the song and raise its pitch together for a sped-up edit.',controls:[['Speed',125,100,200,'%','Original','2× speed']],note:'Starts at 1.25× speed. The song becomes shorter and higher-pitched. Use Tempo control if you want to keep the original pitch.'},
{id:'tempo',name:'Tempo control',icon:'⇥',desc:'Change speed, keep pitch.',detail:'Time-stretch the recording while preserving its pitch.',controls:[['Tempo',120,50,200,'%','Half speed','Double speed']],note:'100% is unchanged. Browser time-stretching may add artifacts at extreme settings, especially on drums.'},
{id:'pitch',name:'Pitch shift',icon:'♪',desc:'Higher or deeper.',detail:'Shift musical pitch while keeping the original duration.',controls:[['Pitch',3,-12,12,' semitones','Octave down','Octave up']],note:'0 is unchanged. An octave is 12 semitones. Large shifts may sound textured; vocal formants are not preserved.'}
];

if (typeof window!=='undefined' && window.SonicI18n) window.SonicI18n.localizeEffects(effects);
